export async function seedIfEmpty() {
  try {
    // 1. Ensure Admin User exists in DB with current admin credentials
    const adminEmail = (process.env.ADMIN_EMAIL || 'prachiagroindustris9696@gmail.com').toLowerCase();
    const adminPass = process.env.ADMIN_PASSWORD || 'Prarabdha@pppagro';
    let adminUser = await User.findOne({ role: 'admin' });
    
    if (!adminUser) {
      console.log('👑 Admin user not found. Seeding default Admin account...');
      const hashedPassword = await bcrypt.hash(adminPass, 10);
      adminUser = new User({
        name: 'Prachi Agro Admin',
        email: adminEmail,
        phone: '9021605160',
        password: hashedPassword,
        role: 'admin',
        isVerifiedDealer: true,
        status: 'active'
      });
      await adminUser.save();
      console.log('✅ Default Admin account seeded successfully:', adminEmail);
    } else {
      // Update existing admin email & password if default changed
      const passMatch = await bcrypt.compare(adminPass, adminUser.password).catch(() => false);
      if (adminUser.email !== adminEmail || !passMatch) {
        console.log('🔄 Updating Admin credentials in MongoDB to:', adminEmail);
        adminUser.email = adminEmail;
        adminUser.password = await bcrypt.hash(adminPass, 10);
        await adminUser.save();
        console.log('✅ Admin credentials updated in MongoDB.');
      }
    }

    if (process.env.AUTO_SEED === 'true') {
      const productCount = await Product.countDocuments();
      if (productCount === 0) {
        console.log('🌱 Product collection is empty. Auto-seeding default products into MongoDB...');
        await Product.insertMany(defaultProducts);
        console.log(`✅ Successfully seeded ${defaultProducts.length} default products into MongoDB.`);
      }

      const categoryCount = await Category.countDocuments();
      if (categoryCount === 0) {
        console.log('📂 Category collection is empty. Auto-seeding default categories into MongoDB...');
        await Category.insertMany(defaultCategories);
        console.log(`✅ Successfully seeded ${defaultCategories.length} default categories into MongoDB.`);
      }
    }
  } catch (err) {
    console.error('❌ Error during auto-seeding:', err.message);
  }
}
